import Foundation

/// Parte 2 das divindades embutidas (Faiths & Avatars + Powers &
/// Pantheons) — mesmo padrão de EmbeddedRules_PartN.swift/
/// EmbeddedKits_PartN.swift, literais Swift direto, sem Bundle/
/// JSONDecoder em runtime. Gerado a partir dos JSONs enviados pelo
/// usuário (pipeline de extração externo) — não editar à mão, regenerar
/// a partir da fonte se os dados mudarem.

let embeddedDeity010: Deity = Deity(
    id: "deneir",
    name: "Deneir",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Lesser Power",
    plane: "the Beastlands",
    alignment: "NG",
    status: nil,
    portfolio: "Glyphs, images, literature, literacy, scribes, pictorial and literary art, cartography",
    aliases: "None",
    domainName: "Brux/Library of All Knowledge",
    superior: "Oghma",
    allies: "Oghma, Azuth, Milil, Mystra, Lliira, Lathander",
    foes: "Cyric, Bane (now dead), Malar, Talos, Mask",
    symbol: "A single candle set above a staring purple human eye with a triangular pupil, or a single lit candle",
    worshiperAlignments: "Any",
    avatarClassLevels: "Mage 28, Cleric 27",
    avatarDescription: "Deneir most often appears as an old, balding sage with a huge flaring white beard and eyes of intense blue or violet (though he has been known to appear younger, especially when in disguise). His voluminous robes are covered in glyphs and symbols that seem to serve as some sort of code to remind him of events and pieces of information, but which cause random effects (some as standard glyphs and symbols, some bizarre miscellaneous spell effects or just odd happenings) to any who touch them. He usually carries quill pens, scrolls, and tomes, and may let some of these fall and be left behind. (This appears to happen accidentally, but in fact always occurs on purpose.) Mortals who recover such things find them to be enchanted pens, spell scrolls, tomes of magical power, or instructions for creating magical items or constructs. He can draw his spells from any school or sphere of magic, but out of long habit he tries never to use fire magic because valuable writings might be destroyed.\n\nAC -3; MV 15; HP 171; THAC0 4; *AT 1\n\nDmg 1d10\n\nMR 70%; SZ L (10 feet)\n\nSTR 15, DEX 19, CON 21, INT 24, Wis 22, CHA 16\n\nSpells P: 12/12/12/12/11/9/5, W: 6/6/6/6/6/6/6/6/6\n\nSaves PPDM 2, RSW 3, PP 5, BW 7, Sp 4\n\nSpecial Att/Def: When attacked, Deneir's first action is usually to leave by the most expeditious means. If forced into a situation where he cannot leave, Deneir can employ any one priest spell and any one wizard spell in the same round, or he can summon a scroll from thin air with whatever spell he desires written on it and then read the spell as his action for a round. Those who have seen him agree that he lacks the wariness, ruthlessness, and strategic sense of one used to battle, and in fact seems absentminded even when attacked. His touch causes confusion as the 4th-level wizard spell when he so desires (no saving throw).\n\nInstead of casting spells or summoning a scroll, Deneir can choose to make a being once more experience the worst glyph or symbol damage that it ever experienced. The same saving throw modifiers that applied when the glyph or symbol was originally encountered apply again.\n\nDeneir cannot be harmed by any spell read from a scroll or any magical effect created by the use of a book or tome. He is immune to charm or illusion/ phantasm spells, spell-like effects, and abilities.",
    briefSummary: "Deneir (Deh-NEER) is the patron of the artist, the illuminator, the scribe, and the cartographer. His is the power to accurately render and describe, to write and to read, and to pass on information.",
    fullText: "Deneir (Deh-NEER) is the patron of the artist, the illuminator, the scribe, and the cartographer. His is the power to accurately render and describe, to write and to read, and to pass on information. He counts as his foes all who destroy, hide, or distort knowledge. He works for Oghma making sure that all that is known and true is accurately recorded in the Great Library. He is portrayed in religious art as a balding uge, flared beard whose eyes are in some way peculiar: Sometimes they are a vibrant violet with triangular pupils, at other times they are a brilliant ice blue, and at yet others they are blazing orbs of blue fire. He is always shown holding a quill pen and carrying or writing in or on a book, scroll, or parchment.\n\nDeneir is caught up in the recording, filing, indexing and maintaining of all that was ever written or depicted. He can appear very absent-minded, and often trails off in midsentence because his mind is racing along other trails of thought even as he speaks. For all his acquaintance with book knowledge, he can be out of touch with the world as it is now—in particular, human customs in practice: He tends to use mannerisms of speech and hold to points of etiquette that disappeared long ago from Faerun—or he may (unintentionally humorously) mix his slang terms or try to sound in vogue and actually sound profoundly dated. When he gets going on a story, he can eat up immense amounts of his listeners' time as he diverges seemingly endlessly in parenthetical substories. For all their length, his tales always convey some vital piece of knowledge to those who wait them out.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity011: Deity = Deity(
    id: "eldath",
    name: "Eldath",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Lesser Power",
    plane: "Elysium",
    alignment: "NG",
    status: nil,
    portfolio: "Quiet places, springs, pools, stillness, peace, waterfalls, druid groves",
    aliases: "None",
    domainName: "Eronia/The True Grove",
    superior: "Silvanus",
    allies: "Mielikki, Silvanus, Chauntea, Selune, Lathander",
    foes: "Malar, Loviatar, Bane (now dead), Amaunator (now dead), Talos, Moander (now dead)",
    symbol: "A waterfall plunging into a still pool without causing any disturbance of its waters, or a circular, sky-blue disk fringed with green ferns",
    worshiperAlignments: "Any",
    avatarClassLevels: "Mystic 30, Cleric 25, Mage 22, Bard 15",
    avatarDescription: "Eldath prefers not to appear in avatar form often; she seems almost shy. When she does appear, it is usually to wounded beings who have found their way into one of her sacred places or to her worshipers. Eldath takes the form of a tall, thin, yet graceful and beautiful translucent female human, nereid, or aquatic elf; she can be seen through at all times. Her feet are bare, her hair looks like spun glass or flowing ice and is colorless like water, and her eyes are deep green. Eldath's green silken garments flow clingily around her, yet the sight of her soothes lustful thoughts rather than arousing them. She radiates stillness and peace. She can draw spells from all schools and all spheres except combat and war. She employs enchantment/charm school spells and charm sphere spells as if she were 40th level. —\n\nAC -3; MV 15, H 24; HP 158; THAC0 2; #AT 1\n\nDmg 1d10\n\nMR 75%; SZL (10 feet)\n\nSTR 13, DEX 24, CON 18, INT 19, Wis 24, CHA 21\n\nSpells P: 13/12/12/12/12/11/8, W: 5/5/5/5/5/5/4/4/3\n\nSaves PPDM 2, RSW 3, PP 5, BW 7, Sp 4\n\nSpecial Att/Def: Eldath is a pacifist, preferring to silently resist and withstand rather than fighting. All nondivine attacks are launched at a -7 penalty to attack rolls within 90 feet of her and at a -5 penalty to attack rolls from over 90 feet to 140 feet of her. To raise a hand against Eldath or cast any offensive spell either at her or with her in its area of effect, the attacking being must first succeed at a saving throw vs. spell penalized by any Wisdom ability score magical defense adjustment bonus the attacker normally has (that is, the bonus becomes a penalty of equivalent amount). Magical defense adjustment penalties remain penalties.\n\nEldath can cast one priest spell and one wizard spell per round. Her touch destroys undead creatures of less than divine power, reducing them instantly and forever to dust. She strives above all things to cast spells that restrain, charm, hold, sleep, or otherwise incapacitate persistent foes rather than casting damaging spells. Her smile alone charms and befriends all creatures of Intelligence 1 to 4.\n\nEldath can levitate and walk on air at will at MV Fl 24- She can project silence akin to the silence, 15' radius spell either as a 90-foot-radius sphere centered on herself or in a path up to 90 feet long and as wide or narrow as she desires so as to target specific beings. She can also employ repulsion, and her touch or passage (within 10 feet of where her feet touch—or would if she walked on the surface) automatically purifies tainted, diseased or polluted matter, and neutralizes all poisons.",
    briefSummary: "Eldath (EL-dath) is the guardian of druid groves, and her presence is felt every place where there is calm. Her druids and clergy often aid other druidic faiths in establishing a grove and sanctifying it.",
    fullText: "Eldath (EL-dath) is the guardian of druid groves, and her presence is felt every place where there is calm. Her druids and clergy often aid other druidic faiths in establishing a grove and sanctifying it. In religious art, Eldath is often depicted as a dark-haired woman dressed in shimmering green or as a dryad or wild elf with blue and green hair. Her singing is heard in every babbling brook and waterfall.\n\nEldath is a pacifist and usually takes no hostile actions even when threatened. This is one of the reasons that Eldath is almost a forgotten power; most Faerunians think of Mielikki, Silvanus, or Chauntea in relation to nature before they think of her. Eldath is enigmatic and speaks seldom. She seems shy, but possessed of unknown depths of character and an unexpressed resolve that cannot be broken. When challenged, she gives before challengers who only later discover that her apparent acceptance and retreat merely drew them out into an untenable position where they are surrounded, out of their element, and their reinforcements have been converted to her side.\n\nLike Mielikki, Eldath serves Silvanus. Eldath sees him as a father figure, but often finds his robustness intimidating to her retiring nature. Mielikki and Eldath have a very close relationship. During the Time of Troubles Mielikki was heard to address her as \"Datha,\" and the two goddesses embraced as sisters.\n\nWhile Eldath opposes all that Tempus stands for, she does not consider him a personal foe. He in turn, is said to consider her naive, but to respect her convictions and generally ignore her.\n\nEldath made the Prime Material Plane her home until very recently, similar to Mielikki. In 1369 DR, the same year that Mielikki established an Outer Planes realm, Eldath also moved her home realm, the True Grove, to Elysium. Where she received the divine burst of power to make such a huge move is unknown; sages have considered Eldath's faith a shrinking one for centuries. However, these same scholars speculate that wherever she received the power from, it may be related to the official shift toward good that Eldath herself made apparent in picking Elysium as her home plane.\n\n(Among themselves, church scholars list Mielikki, Mystra, or Chauntea as likely candidates for help in the move.) The shift itself surprised no one, and Eldath still welcomes the same worshipers and clergy members within her fold. Legend holds that Eldath's worshipers may still visit the True Grove even before their deaths through gates in places where it could formerly bft. reached: near the upper reaches of the Unicorn Run in the High Forest, in the Elven Court near Lake Sember or near Elventree, at Eldath's Water in the Misty Forest, in the depths of the Forest of Tethir, in the dense heart of the King's Forest in Cormyr, atop Oak Hill in the Border Forest north of the River Tesh, at various locales in Turmish, and in a dozen or more other wooded areas.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity012: Deity = Deity(
    id: "gond",
    name: "Gond",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Intermediate Power",
    plane: "the Outlands",
    alignment: "N",
    status: nil,
    portfolio: "Artifice, craft, construction, smithwork \"fl",
    aliases: "Zionil (Durpar, Estagund, and Var the Golden)",
    domainName: "Outlands/Wonderhome",
    superior: "Oghma",
    allies: "Lathander, Oghma, Waukeen (missing), Tempus",
    foes: "Talos",
    symbol: "A shining toothed wheel or cog with four spokes, in ivory, bone, or metal",
    worshiperAlignments: "Any",
    avatarClassLevels: "Mage 27, Cleric 20, Thief 19, Fighter 15",
    avatarDescription: "Gond's avatar is rarely seen by mortals outside his temples; he much prefers to manifest in a lesser manner. His avatar sometimes appears as a short, slight man with straw-blond hair, at others times as a burly, red-hued smith, and at yet others a gnome. In any form, his sharp, bright, dark eyes stare out of a forge-scarred face that always bears an alert, inquiring expression. He wears a scorched smith's smock over nondescript leathers, and at will can summon into being around himself glassteel plate armor that hovers over his body at a close distance, piece by piece, rather than actually encasing his form. He has a mighty hammer that he uses at his divine forge and as a weapon when necessary. He can draw spells from any school or sphere, and casts alteration spells at double effect in all respects and a -2 penalty to applicable saving throws.\n\nAC -5; MV 15; HP 188; THACO 6; #AT 5/2*\n\nDmg 2d4+27 (hammer of thunderbolts [+11], +12 STR, +2 spec, bonus in hammer) or 1d10 (arquebus)\n\nMR 65%; SZ L (10feet)\n\nSTR 24, DEX 19, CON 21, INT 25, Wis 20, CHA 16\n\nSpells P: 12/12/11/10/7/5/2, W: 6/6/6/6/6/6/6/5/5\n\nSaves PPDM 2, RSW 3, PP 5, BW 4, Sp 4\n\n: * Only one attack per round is possible with the hammer of thunderbolts, but normal melee attacks apply for a hammer +3.\n\nSpecial Att/Def: When he uses a weapon in combat, Gond often uses a hammer of thunderbolts. He can strike with it or hurl it once a round and never tires of using it. His hurling range is 360 feet, and he strikes with the hammer as if h e were wearing a girdle of giant strength and gauntlets of ogre power (+5 hammer damage bonus and +6 gauntlet damage bonus; his actual Strength equals the girdle). It strikes dead any giant it hits, along with ogres, ogre magi, trolls, ettins, and clay, flesh, and stone golems. When it hits, it stuns all creatures within 90 feet for one round. Gond also loves to use arquebuses and can instantly summon a fully loaded and ready to fire arquebus into his hands whenever he desires, dismissing an old one and summoning a new one every round. He has also been known to use an assortment of magical staffs and a hammer +3, and he can summon any nonunique magical item in the PHB, DMG, Tome of Magic, or any FORGOTTEN REALMS campaign setting product that is not an artifact or in the possession of another deity to his hands in one round.\n\nMetal weapons and weapons manufactured through smelting, forging, or working with metal tools cannot harm Gond. Once per turn he is able to disjunct all magical items in his vicinity (as the 9th-level wizard spell Mordenkainen's disjunction). Normal metallic items striking him are disinte-* grated automatically (no saving throw); magical metallic items must succeed at an item saving throw vs. disintegration at a -5 penalty ot be disintegrated. In either case, the metallic item does Gond no damage. Golems and animated constructs will not lift a hand against Gond; neither can he be harmed by firearms such as arquebuses.",
    briefSummary: "Gond (GOHND) Wonderbringer is the god of blacksmiths, woodworkers, inventors, and engineers.",
    fullText: "Gond (GOHND) Wonderbringer is the god of blacksmiths, woodworkers, inventors, and engineers. In religious art, he is most often portrayed as a burly, red-hued smith, with a mighty hammer and a forge and anvil that allow him to craft the stuff that stars are made from.\n\nGond serves Oghma along with Deneir and Milil. He gives the ideas Oghma holds in his portfolio concrete form and inspires others to make new things. He has grown very independent as his own power waxes, and hi relationship to Oghma is already only dimly remembered at times by mortals. In Durpar, Estagund, and Var the Golden, Gond is worshiped as part of the Adama, the Durparian concept of a world spirit that embraces and enfolds the divine essence that is part of all beings. Here he is known as Zionil, patron of inventors, craftfolk, and creators.\n\nGond is always making new things. He often presses Oghma for their release into the mortal world without thinking through completely the impact they will have. He is fascinated with making the theoretical real and either does not consider or often does not care about the implications for the use of his inventions and discoveries. He has a constant need for bizarre components as well as raw materials for his work, and so may overlook shady sponsors for specific jobs provided that they pay well in materials, knowledge he can use, or future favors. He can be distracted, businesslike, sarcastic, or patronizing as well as incredibly helpful and brilliant. He is dedicated to his faithful, and though he sometimes does not immediately respond to them because he is busy, he always ensures that their needs are met.\n\nDuring the Time of Troubles Gond, in the avatar of a gnome, washed ashore on Lantan. His true nature was quickly discovered, and the deity was revered and worshiped there until the crisis passed. As a result, Gond gave the secret of smoke powder to the Lantanna, and arquebuses, stamped on the butts of their stocks with the symbol of Gond, have been shipped at a steady trickle to western ports since 1358 DR.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity013: Deity = Deity(
    id: "grumbar",
    name: "Grumbar",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Greater Power",
    plane: "the Elemental Plane of Earth",
    alignment: "N",
    status: nil,
    portfolio: "Elemental earth, earth elementalists, solidity, changelessness, oaths",
    aliases: "Etugen (Hordelands)",
    domainName: "Elemental Plane of Earth/The Great Mountain",
    superior: "None",
    allies: "Geb, Garl Glittergold, Dumathoin, Kurtulmak, Laduguer, Urogalan, Skoraeus Stonebones",
    foes: "Akadi, Urdlen",
    symbol: "Mountains, often against a purple field",
    worshiperAlignments: "Any",
    avatarClassLevels: nil,
    avatarDescription: nil,
    briefSummary: "TURN UNDEAD: SP: No, Cru: No, Mon: No, Sha: Yes, if good",
    fullText: "TURN UNDEAD: SP: No, Cru: No, Mon: No, Sha: Yes, if good\n\nCMND. UNDEAD: SP: No, Cru: No, Mon: No, Sha: Yes, if neutral or evil\n\nAll specialty priests, crusaders, monks, and shamans of Grumbar receive religion (Faerunian) as a bonus nonweapon proficiency. Grumbarryn priests are strongly encouraged to learn engineering or survival (mountain) in addition to their required proficiencies. All shamans of Grumbar receive elemental earth as one of their major spheres in addition to their normal spheres of magic.\n\nBefore the Time of Troubles, all of the elemental cults had clerics in their ranks. Now, only specialty priests remain. Why the elemental lords decided to convert their clerics to specialty priests is unknown, but most actions that they take are cryptic and difficult to grasp. Since the Godswar, the Grumbarryn church has added a small order of monks and an order of crusaders to the church to fulfill duties in the ranks of the priesthood left ill attended with the loss of Grumbarryn clerics.\n\nMembers of the Grumbarryn priesthood often take it upon themselves to resist change at every possible turn. The expansionist activities of other churches frequently face opposition from devout followers of die Earthlord. This opposition takes many forms, both passive and active. Priests of Grumbar may gather together to summon an elemental for the purpose of destroying the foundation of a church under construction, or they may instigate an armed attack against followers of other powers. Their resistance to change does not limit itself to other churches, and includes changes in government, in organizations, and even in geography. Despite their fervent resistance to change, Grumbar's priests are not considered fanatics. Their actions tend to be well thought out, and few of the decisions made by the church are ever arrived at in haste.\n\nGrumbar's priests are organized into Holds. Each Hold comprises 21 priests—seven specialty priests, seven monks, and seven crusaders—and as many members of the laity as the Hold can support. The high priest is always a specialty priest. Each Hold is composed of members of a similar alignment. While this sort of organization does reduce tensions within a particular Hold, it also causes the Grumbarryn faith to be viewed differently from region to region. Most priests stay in the same geographic area as other members of their Hold, but others wander the face of Faerun, spreading the Grumbarryn faith and watching for threats to their religion. Most Holds of devout followers are small and their congregations and clergy members remain intent on whatever task the Grumbarryn church elders have set them for the year. In primitive or nomadic societies (such as those of the Tuigan), Grumbar is served by shamans allied to no particular Hold.\n\nNovice Grumbarryn are referred to as the Unspoken. Upon taking the Oath of Landwalking, they become full priests and are known as the Oathbound. In ascending order of rank, the titles in general use by the Oathbound are: Faithful Bedrock, Granite Flagstone, Righteous Rock, Buttress of the Faith, Steadfast Pillar, Devoted Tribune, Loyal Architrave, Founding Fist, Unchanging Bastion, Surmounting Arch, Loyal Vault, and Keystone of Grumbar. Specialty priests of Grumbar are known as earthwalkers. Monks of Grumbar are known as Cornerstones.\n\nShrines and temples of Grumbar are always made of stone. Most have splendid vaulted ceilings and walls to give the site the feeling that a worshiper is down within the living rock. Wood is a rare commodity in Earthlord temples because of the church's strong preference for stone, but gems and other precious minerals adorn most surfaces abundantly.\n\nDogma: The teachings of the church are built around a strong resistance to change, especially radical change. Important Grumbarryn followers, priest and warrior alike, are frequently portrayed in teaching stories and fables that augment the faithful's belief in the importance of resisting change. Grumbarryn doctrine also speaks of the holiness and absolute quality of oaths. Grumbarryn take oaths with extreme seriousness and would never break one upon pain of being cast out of their faith.\n\nNovices in the Grumbarryn faith are charged as follows: \"The eternal Grumbar is perfect and unchanging. Strive to be more like the eternal one, not to change or allow change to happen. One's given word is the bedrock upon which a stable society is built. To break an oath is to cause a crack in the foundation of civilization. Go forth and spread the word of Grumbar and show through your works the stability and safety he brings.\"\n\nDay-to-Day Activities: Those who follow the Earthlord can often be found in public preaching against the evils of spelljamming and—to a lesser degree—criticizing those who would board ships and set sail to uncharted lands. Seeking out new lands is a noble calling, but Grumbarryn argue that there are more lands left to explore on the large continent of Faerun, Karatur, and Zakhara. The sentient beings of Abeir-Toril should spread out slowly and steadily to know the every crevice of its surface. Hurling oneself into the void of space is foolhardy recklessness at its extreme. Many of the clergy members preach that \"more than enough problems exist to occupy our time here at home without looking for new troubles.\" Grumbar's clergy members also take stances against changes in the social code, changes in government, the building of new landmarks that change the face of the land, such as dams, and changes in their own religion. Many of the older and higher-level clergy members are still trying to ascertain what error of conduct they committed that caused Grumbar to change all the church's clerics into specialty priests after the Godswar.\n\nHoly Days/Important Ceremonies: The faithful are expected to pray to Grumbar each day upon rising and each night before resting, thanking him for keeping the earth stable and secure yet another day. Other than this daily ceremony, the church observes two personal ceremonies and a yearly festival.\n\nThe Oath of Landwalking is a solemn promise undertaken by all members of the Grumbarryn faith upon entering the priesthood that forbids them from traveling through the air or by sea. Only in the most dire of circumstances would priests of Grumbar take to the enemy element of air. Even then, they would probably suffer a loss of spells. Travel over water is allowed only when the church would benefit as a result of the sacrifice. Such benefits include the dedication of a branch temple or shrine in a new land, obtaining a new source of minerals or stone to replace one now mined out, or even the discovery of a new earth-based creature.\n\nThe Brotherhood of Earth is the ceremony that Grumbarryn specialty priests undergo that allows them, upon reaching a certain level of skill, to call forth their elemental brothers from the Elemental Plane of Earth. The ceremony is preceded by a day of fasting and prayer, after which the elemental is summoned. When it answers, it is given a gift of gems and gold to carry back to Grumbar with the good wishes of his faithful.\n\nOn Midwinter, the church holds a festival celebrating the completion of another year in the eternal church of Grumbar. During this festival church leaders and elders gather to plan the faith's activities during the upcoming year. These plans, once set, are never varied from during the year and can only be changed at the next Midwinter festival.\n\nMajor Centers of Worship: Major temples to Grumbar lie hidden in the Spine of the World Mountains, the Giantspire Mountains, the Muaraghal (the east wall of Halruaa), the Wu Pi Te Shao Mountains, and the Orsraun Mountains. All are secret, hidden temples located in natural caverns or crafted with utmost skill to look like the terrain in which they are set until a traveler is almost on top of them. The southern part of the Muaraghal houses the most sacred site of the Grumbarryn church and most Grumbarryn try to make a pilgrimage to it once in their lives.\n\nAffiliated Orders: The Grumbarryn monastic order is known as the Disciples of the Changeless Face. They are a stoic and spartan order whose members preserve the knowledge of how things are so that changes can be detected and countered. The crusading order of the faith is the Sardonyx Knights. This order's members guard the holy sites of the faith against infidels and lead the few field actions the church undertakes. They are also responsible for punishing those members of the faith who forswear oaths they have taken.\n\nPriestly Vestments: Grumbarryn tend to be large, solid men, and the ceremonial vestments of the faith aim to make them look as large (and in their minds, stable) as possible. Ritual garb includes a brown cassock, belted at the waist; a brown leather hood or hat; a huge cloak of gray-green and rust brown with artificially extended and stiffened shoulder pads that make the wearer took as wide as she or he is tall; and platform clogs worn over soft leather boots. The holy symbol of Grumbar, a large ruby or sardonyx carved with Grumbar's symbol and incorporated into a ring or pendant, is always worn.\n\nAdventuring Garb: Adventuring priests wear travel cloaks, boots, and clothing in the same earth-tone, gray, or black colors typical of their faith, but they understand that bulky clothing that makes one look large offers little real protection from a knife thrust or fired arrow. Bulky armor is another matter entirely, and Grurabarryn wear the most protective armor they can afford.\n\n## Specialty Priests (Earthwalkers)\n\nREQUIREMENTS: Strength 12, Wisdom 12\n\nPRIME REQ.: Strength, Wisdom\n\nALIGNMENT: LG, LN, N, LE\n\nWEAPONS: All bludgeoning (wholly Type B) weapons\n\nARMOR: Any, but the bulkier the better\n\nMAJOR SPHERESS: Elemental earth, combat, healing, protection\n\nMINOR SPHERES: Divination, elemental fire, elemental water, necromantic, travelers, wards\n\nMAGICAL ITEMS: Same as clerics, except forbidden from using magical items with air-based or flying effects (flying carpet, ring of feather falling, cloak of the bat, etc.)\n\nREQ. PROFS: Stonemasonry\n\nBONUS PROFS: Gem cutting or mountaineering (pick one)\n* Mountain dwarves, duergar, gnomes (rock gnomes), and svirfneblin may be earthwalkers, though the cultural peer pressure against dwarves and gnomes walking such a life path is very strong in their societies.\n* Earthwalkers may cast wizard spells from the elemental earth school in addition to priest spells. These spells are cast as if the earthwalker were a mage of the same level. For example, a 3rd-level earthwalker casts wizard spells as a 3rd-level mage. Earthwalkers pray for their wizard spells instead of studying to memorize them, and chosen wizard spells replace priest spells potentially available for use that day. (In other words, the wizard spell occupies a priest spell slot.) Earthwalkers gain access to 8th-level wizard spells at 16th level and 9th-level wizard spells at 18th level. An earthwalker must have a Wisdom of 18 or higher and an Intelligence of 16 to gain access to the 8th level spells, and a Wisdom of 18 or higher and an Intelligence of 18 to gain access to the 9th-level spells. If an earthwalker is able to gain high-level wizard spells, every 8th-level spell prayed for occupies a 6th-level priest spell slot and every 9th-level spell prayed for occupies a 7th-level priest spell slot. Earthwalkers are always able to read elemental earth spells on scrolls or in wizard spellbooks as if they knew read magic (but studying spells from a spellbook is useless to them). No more than threequarters of an earthwalker's total number of spells available (round down) can be taken as wizard spells.\n* All earthwalkers gain a +2 bonus to saving throws vs. the harmful effects of earth-related spells and pelletlike, granular, or electrical breath weapons.\n* As Grumbar's boon to them, earthwalkers are not deterred in their movement by any type of metal armor or armor fashioned of other materials mined from the earth. In fact, this type of armor feels as light as air to them. They do not count the weight of such armor against their carrying limits, nor does it affect their encumbrance.\n* At 5th level, earthwalkers can summon one 8-HD earth elemental once a day. This elemental remains under the control of the earthwalker for one hour and cannot be taken control of by another creature. If the summoner is killed or struck unconscious, the summoned elemental goes on a rampage, attacking everyone in sight except its summoner until its one-hour time limit upon the Prime Material has elapsed. It is important to note that the elemental summoned is not a servant of the earthwalker, but rather is looked upon as an agent of Grumbar that is to be respected. The ability to summon an elemental is granted once each day when earthwalkers receive their normal complement of spells.\n* At 7th level, earthwalkers have the ability to cast stoneskin (as the 4thlevel wizard spell) once per day.\n* At 9th level, earthwalkers have the ability to cast earthenport (as the 5th-level priest spell) once per day.\n* At 9th level, earthwalkers can summon one 12-HD earth elemental once a tenday. All the same conditions apply as for summoning an 8- HD earth elemental.\n* At 13th level, earthwalkers can summon one 16-HD earth elemental once a tenday. All the same conditions apply as for summoning an 8- HD earth elemental.\n* At 15th level, earthwalkers can move through the Elemental Plane of Earth without need for food, water, or air.\n* Earthwalkers who work together can summon an elemental of greater Hit Dice than they would otherwise be able to alone. For example, a 5th- and 9th-level priest could summon a 16-HD elemental. As long as both summoners remain alive, the elemental remains under their control for one full hour. If one of the summoners is killed or struck unconscious, the summoned elemental goes on a rampage, attacking everyone in sight until its one-hour time limit upon the Prime Material has elapsed. It then returns to the Elemental Plane of Earth. The participants in such a combined summoning attempt must abide by time restrictions for further elemental summoning apportioned by their levels. In the above case, the 5th-level priest would have summoned his 8- HD elemental for the day and the 9th-level priest would have summoned her 12-HD elemental for the tenday.\n\n## Grumbarryn Spells\n\n| Name | Level | Sphere(s) |\n| --- | --- | --- |\n| Earthenair | Level 3 | Elemental Earth |\n| Earthenport | Level 5 | Elemental Earth |\n\nCategory:Faerunian Gods",
    categories: ["Faerunian Gods"]
)

let embeddedDeity014: Deity = Deity(
    id: "helm",
    name: "Helm",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Intermediate Power",
    plane: "Mechanus",
    alignment: "LN",
    status: nil,
    portfolio: "Guardians, protectors, protection",
    aliases: "None",
    domainName: "Mechanus/Everwatch",
    superior: "None",
    allies: "Torm",
    foes: "Bane (now dead), Bhaal (now dead), Garagos, Mask, Shar, Talos",
    symbol: "An open, staring eye with a blue pupil and outline painted on the back of a right-hand war gauntlet or the palm of a left-hand war gauntlet",
    worshiperAlignments: "LG, NG, CG, LN, N, CN",
    avatarClassLevels: "Fighter 35, Cleric 23",
    avatarDescription: "Since the Time of Troubles, Helm has been increasingly reluctant to appear in Faerun in avatar form, typically doing so only when a senior priest or temple is directly threatened and he is called upon. Helm always appears as a giant man in full plate armor, his face concealed by his helm. His height varies from one appearance to the next. He can draw spells from any sphere.\n\nAC -5; MV 15 or Fl 24; HP 222; THACO -10; #AT 5/2\n\nDmg 2d4+15 (bastard sword +3, + 10 STR, +2 spec, bonus in melee weapons)\n\nMR 65%; SZ H (anywhere from 14 to 20 feet)\n\nSTR 22, DEX 18, CON 21, INT 19, Wis 24, CHA 17\n\nSpells P: 13/12/12/12/12/9/3\n\nSaves PPDM 2, RSW 5, PP 4, BW 4, Sp 6\n\nSpecial Att/Def: If the God of Guardians appears in a place too small to permit his full height, only his upper torso appears, floating and flying about at the given flying rate. Helm may use any sort of weapon and is considered specialized in all forms of melee weapons; he has most often been seen wielding a bastard sword +3 two-handed. He can surround himself with a ring of floating shields that reflect back all magic, psionic, breath weapon, and gaze attacks 100% at their sources if he wishes, rather than cast a spell during a round. If a shield is destroyed, it explodes into a 100-foot-long cone of cold 20\n\nPriestly Vestments: Priests of Helm wear spotless, shining, (often everbright-enchanted), unblemished full plate armor with open-faced helms (a visor reduces vision). Often the helms are topped with plumes. Such armor may be accessorized with red cloaks and tabards of steel gray, and such garments—or the armor itself—may be adorned with the Unsleeping Eye in the center of both back and breast. In southern regions, Helmite clergy members often wear the finest full plate armor set with gems and worked with gold filigree in designs that accentuate great golden eyes set in the centers of their chests (on the breastplates) and backs. In areas where heavily armored clerics are frowned on, the armor is reduced to a set of heavy shoulder plates, but the helm remains in any case.\n\nAdventuring Garb: Because of the useful nature of the ceremonial gear of the priests of Helm, it is worn in the field as well as for ceremonial purposes, unless it is decorated with such costly materials that the priest fears it will attract thieves, in which case a more utilitarian version of the same full plate armor is worn. In either case, the armor is dominated by the symbol of Helm's eye on the chest, often shown in a sunburst or as the topmost level of a stepped pyramid.",
    briefSummary: "Helm (HELM) is the epitome of the guardian, the watcher, the guard, and has in years past been greatly venerated by those who need to remain watchful for evil at their doorsteps.",
    fullText: "Helm (HELM) is the epitome of the guardian, the watcher, the guard, and has in years past been greatly venerated by those who need to remain watchful for evil at their doorsteps. He was once a much more powerful god, but has fallen upon hard times through two actions. During the Time of Troubles, Helm was left with his powers and ordered to hold the gates to the Outer Planes against the other powers of the Realms when the other deities were stripped of their power and confined to the surface of Abeir- Toril. Helm did so all too successfully, and much of the resulting destruction and deific turmoil caused by the many divine deaths of the Godswar is laid at his feet.\n\nHelm remained strong in the South, but experienced a further setback when his priests became deeply involved in an invasion of the True World of Maztica. Their unflinching and often brutal actions counted further against the god's reputation. Because of the inflexible and cold reputation those actions gained him, Helm's star is fading at a time when Torm and Gond are attracting new followers.\n\nHelm is difficult to understand and is often viewed as emotionless, heartless, and devoted only to his duty or goal at the cost of all mortal consideration. While he is devoted to the point of obsession, he is not heartless, but merely a stern disciplinarian. He is fond of children and has been known to be most uncharacteristically lenient (for Helm) when dealing with small infractions by them or on their behalf.\n\nIn attempting to comprehend Helm's driven nature, many mortal sages have attempted to account for him throwing himself into his work by blaming his behavior on a broken heart caused by long-unrequited or spurned love. Others say he lost a great love to tragedy or eternally grieves for a lost relative, such as a brother, sister, or child. Still others account for his behavior more coldly as a burning ambition to become the greatest of deities. Helm has never given credence to any of these theories, as he considers such speculations frivolous use of time that could be spent more honestly at productive work.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity015: Deity = Deity(
    id: "ibrandul",
    name: "Ibrandul",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Lesser Power",
    plane: "Pandemonium",
    alignment: "CN",
    status: "Dead",
    portfolio: "Caverns, dungeons, the Underdark, skulks",
    aliases: "None",
    domainName: "Formerly Phlegethon/Ibrandyllaran; currently adrift in the Astral Plane",
    superior: "None",
    allies: "Mask, Ilmater",
    foes: "Shar, Lathander, Lolth",
    symbol: "Four interlocking silver circles on a dark purple background",
    worshiperAlignments: "CG, N, CN, NE, CE",
    avatarClassLevels: "Mage 24, Fighter 20, Cleric 17",
    avatarDescription: "Ibrandul (currently played by Shar) favors two forms, the Stalker and the Skulker. The Stalker is a monstrous lizard of the depths that looks like a fire lizard with a long, thick tail. He has a gray-scaled body with a red-and-brown-mottled back and a reddish underside. He resembles a wingless, elongated red dragon. The Stalker is said to roam the endless caverns of Pandemonium hunting other predators and is the form most commonly portrayed in religious art in Calimshan and the Sword Coast North.\n\nThe Skulker might be mistaken for a stone golem or earth elemental. He appears to be a humanoid of black and gray stone worn smooth as if long exposed to the eroding force of howling winds. The Skulker has no specific facial features, but his eye patches glow like cool magma in utter darkness. The Skulker frequently shapechanges to alter his appearance, taking the shape of anything from a chisel-featured, bare-chested massive human known to natives of Calimshan to that of a stony roperlike creature known to the drow. The Skulker prefers to appear to mortals while lurking in perfect darkness where he is visible only by his glowing eyes and to aid or hinder others through wit and voices in the gloom.\n\nIn either form, Ibrandul can cast spells from any school or sphere of magic. He favors spells from the spheres of elemental earth, sun (reversed, darkness-creating effects only), and travelers, and cannot cast spells that create light for more than a single instant. (Hence, for example, he can cast « fireball, which has an instantaneous duration, but cannot cast glitterdust.)\n\nAC -2; MV 12 (Stalker) or 15 (Skulker); HP 188; THACO 1; #AT 5 (Stalker) or 2 (Skulker)\n\nDmg 1d12+11/1d12+11/1d12+11/1d12+11/2d10+11 (claw/claw/claw/daw/bite, +11 Str) or 2d10+11 (bludgeoning appendage¥2, +11 Str)\n\nMR 55%; SZ G (up to 60 feet in length—Stalker) or M to H (6 feet to 16 feet- Skulker)\n\nStr 23, Dex 19, Con 23, Int 21, Wis 19, Cha 17\n\nSpells P: 10/9/9/8/5/3/2, W: 5/5/5/5/5/5/5/5/4\n\nSaves PPDM 3, RSW 3, PP 4, BW 4, Sp 4\n\nSpecial Att/Def: The Stalker can attack five times per round—four attacks with his claws and one with his powerful bite. Regardless of the shape he assumes, the Skulker bludgeons opponents with two powerful appendages that may resemble arms, tentacles, or something else.\n\nIbrandul (in either form) can stand motionless against any rock face and remain completely undetectable by any nonmagical means. He can sink directly into the wall and move uninhibited within it at will, yet still observe events outside the wall as if he were standing in the open air. He can also negate any blindness penalty to his attack rolls (see below) by striking from within a stone wall (provided he can reach his target).\n\nIbrandul can see in perfect darkness as if he were standing in broad daylight, but he suffers a blindness penalty (-4) if exposed to light with the minimum brightness of a continual tight spell. However, he can create darkness, 15' radius at will in addition to his",
    briefSummary: "Worshipers in Calimshan and other areas of the Shining South claim that Ibrandul (ih-BRAN-duhl) watches over humans who must venture into hostile underground areas, aiding and guiding those who serve him when they are in need.",
    fullText: "Worshipers in Calimshan and other areas of the Shining South claim that Ibrandul (ih-BRAN-duhl) watches over humans who must venture into hostile underground areas, aiding and guiding those who serve him when they are in need. Ibrandul's worship began in the prehistory of Calimshan, even before Hthe founding of the Shoon Empire, which is now known as lltkazar. Some time after the defeat of the Djen, a tribe of nomadic humans was abducted from the Calim Desert by dark elf raiders from the city of Guallidurth, located deep beneath the desert sands. These humans served the drow as slaves for centuries, unable to flee the subterranean city because of their fear of the all-enveloping darkness.\n\nThe humans eventually escaped when a monstrous lizard emerged from the darkness, drove off the dark elf overseers, and led the slaves into the surrounding wilds of the Underdark. Some of the former slaves eventually returned to the surface and brought with them tales of the Lord of the Dark Depths to the tribes of the surface. Others remained in the dark tunnels, living in small, nomadic bands and subsisting by raiding the farms and caravans of the drow of Guallidurth and the humans of the surface. The subterranean dwellers slowly evolved into skulks—a cowardly race of humanoids with chameleonlike abilities—through a side-effect of one of the spells granted by the Skulking God. Both the humans of the surface and the skulks of the Underdark continue to worship Ibrandul, albeit with slightly different representations and sets of beliefs. Since then Ibrandul's worship has quietly spread to many locations with access to the Underdark, including Undermountain beneath Mt. Waterdeep.\n\nDuring the Time of Troubles, Ibrandul was spotted wandering the Underdark beneath Waterdeep. Unbeknownst to his worshipers, Ibrandul was killed during the Godswar by Shar. The now-petrified remains of his avatar are believed to lie at the bottom of a vast chasm in a lost level of Undermountain. Shar has always jealously guarded her rulership over darkness and those who work in it, and when Ibrandul was tremendously weakened by being forced into a minor avatar form (as all the powers were) during the Time of Troubles, Shar killed him for daring to subvert followers away from her ranks. When the gods ascended to the heavens, Shar had acquired the power and portfolio of Ibrandul. Shar's guise as Ibrandul is quite useful to her, allowing her to subvert the worship of her hated enemy Selune without drawing attention to her most faithful worshipers, the nightcloaks. Shar/Ibrandul enjoys the delicious irony of secretly eroding the power of the Lady of Silver, particularly in the city of Waterdeep, one of the seats of Selune's power.\n\nIbrandul was a taciturn and moody power, and Shar stills plays him as such when she speaks for him or has one of her avatars behave and appear as his used to. He displayed all intense emotions simply by flicking his tongue or blinking his eyes at a quicker pace. He radiated an aura of gloom, darkness, and ages long forgotten. He was always restless, wanting to stalk off into the dark and roam the tunnels of the Underdark searching for those might harm his followers.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity016: Deity = Deity(
    id: "ilmater",
    name: "Ilmater",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Intermediate Power",
    plane: "Bytopia",
    alignment: "LG",
    status: nil,
    portfolio: "Endurance, suffering, martyrdom, perseverance",
    aliases: "Ayuruk (among the peoples of the Great Glacier)",
    domainName: "Shurrock/Martyrdomain",
    superior: "Tyr",
    allies: "Tyr, Torm, Ibrandul (now dead), Lathander",
    foes: "Loviatar, Malar, Talos , Bane (now dead), Bhaal (now dead), Myrkul (now dead)",
    symbol: "A pair of white human hands bound at the wrists with blood-red cord or (older) a blood-stained rack",
    worshiperAlignments: "Any",
    avatarClassLevels: "Monk 35, Cleric 32, Paladin 20, Mage 18",
    avatarDescription: "Ilmater appears as a man with broken joints who drags himself around in obvious pain using his smashed hands and ravaged limbs despite the agony activity causes. He is short, burly, and wears only a breechcloth. His balding head sports a homely, kindly face, and his hairy body is crisscrossed with scars, open cuts, burns, and other marks of torture. He can cast spells from any priest sphere or wizard school, but rarely casts any spell that causes any form of damage to another unless in retribution for sadistic acts performed by others. All positive forms of healing and necromantic sphere spells he casts are at double strength.\n\nAC -5; MV 15; HP 224; THACO -2; #AT 3/1*\n\nDmg ldlO+9 (+9 STR, +10 spec, bonus in punching, +9 chart bonus**)\n\nMR 80%; SZL (12 feet)\n\nSTR 21, DEX 13, CON 25, INT 19, Wis 23, CHA 18\n\nSpells P: 15/14/13/13/12/11/9, W: 5/5/5/5/5/3/3/2/1\n\nSaves PPDM 2, RSW 5, PP 4, BW 4, Sp 6 : * Includes extra unarmed specialization attack. \"Using the PHB or Complete Fighter's Handbook or Complete Priest's Handbook unarmed combat rules. Using PLAYER'S OPTION™: Combat & Tactics, he is considered a grand master.\n\nSpecial Att/Def: Ilmater does not use a weapon. He most often does not even defend himself against attacks, simply suffering the damage he is dealt. He regenerates 6 hit points a round, though his broken physical form never reflects this healing. He can function perfectly well without being destroyed until at -213 hit points. He only strikes out in anger with spells or fists in retribution for extreme acts of cruelty and sadism or when defending another from attacks. He also strikes out with his fists to deflect missile attacks directed at himself and others (with a successful attack roll per missile) and to target specific items that he deems dangerous. He is considered to be specialized in martial arts, a grand master in martial arts, or specialized in punching, depending on the unarmed combat rules in use (see the monk class in Appendix I: Priest Classes).",
    briefSummary: "Ilmater (Ihl-MAY-ter) offers succor and calming words to those who are in pain, oppressed, or in great need. He is the willing sufferer, the one who takes the place of another to heft the other's burden, to take the other's pain.",
    fullText: "Ilmater (Ihl-MAY-ter) offers succor and calming words to those who are in pain, oppressed, or in great need. He is the willing sufferer, the one who takes the place of another to heft the other's burden, to take the other's pain. He is the god of the oppressed and unjustly treated.\n\nIlmater is quiet, kind, good-spirited, and slow to anger. He appreciates a humorous story and has a rather rustic humor himself. When his avatar appears, he takes assaults upon his person passively and rarely lifts a hand against another. He is not totally nonviolent, though, as many often assume by his doctrine of endurance. When facing cruelties and atrocities his rage can boil up, and then he is a figure of frighteningly righteous wrath. His appearance can frighten the young, but he takes great care to reassure them as he treasures children and all young creatures, taking exceptional offense at those who would abuse or harm them.\n\nIlmater is allied to and serves Tyr, aiding the blinded god in his travels and teaching him to live without his sight but to rely more upon his feelings. He is also on very good terms with Torm, who also serves Tyr, and the three deities are known collectively as the Triad.\n\nIlmater's symbol in the early days was the blood-stained rack, but since the Godswar the use of a pair white hands bound with blood-red cord has come into almost exclusive use. This newer symbol has increased Ilmater's popularity in the world at large.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity017: Deity = Deity(
    id: "istishia",
    name: "Istishia",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Greater Power",
    plane: "the Elemental Plane of Water",
    alignment: "N",
    status: nil,
    portfolio: "Elemental water, water elementalists, purification through cleansing, wetness",
    aliases: "None",
    domainName: "Elemental Plane of Water/Sea of Timelessness",
    superior: "None",
    allies: "Deep Sashelas, Trishina, Eadro, Persana, Shekinester, Surminare, Valkur the Mighty, Water Lion",
    foes: "Kossuth",
    symbol: "A cresting wave or a drop of water",
    worshiperAlignments: nil,
    avatarClassLevels: "30-HD Water Elemental, Cleric 30, Mage 30",
    avatarDescription: "Istishia has been seen only three times in written record in avatar form on Abeir-Toril, one of which was at the time of the creation of the Sea of Fallen Stars. Istishia appears as a 20- to 30-foot-thick column of water that moves' effortlessly over or through whatever obstacles are placed in his path. He has also been known to split his water form up into two or more parts to confuse his enemies. His movements sound like the surf pounding on the shore, and his voice is the sound of rushing water, a babbling brook, and a gentle rain all at once. He casts spells from the elemental water, healing, and weather spheres and the elemental water school.\n\nAC -4; MV 12; HP 296; THAC0 -9; *AT 2\n\nDmg 15d6\n\nMR 50%; SZ G (40 to 60 feet)\n\nSTR 20, DEX 24, CON 21, INT 19, Wis 19, CHA 13\n\nSpells P: 12/11/11/10/9/9/8, W: 7/7/7/7/7/7/7/6/6\n\nSaves PPDM 2, RSW 3, PP 4, BW 4, Sp 4\n\nSpecial Att/Def: So long as there is water present somewhere for him to issue forth from when he first appears, Istishia is considered a native of the Prime Material Plane in any crystal sphere he appears in. This makes him immune to the adverse effects of such spells as anti-magic shell, protection from evil/good, and holy word on creatures from other planes. He also has total immunity to any spell that adversely effects water, such as transmute water to dust.\n\nIstishia can easily swamp or overturn boats and ships of any size in one round and stop or slow any water vessel in the same amount of time. Istishia may use the same abilities as any elemental watet kin. Whenever Istishia successfully attacks in combat with his gigantic wave fists, the target creature must make a successful saving throw vs. breath weapon at a -2 penalty or die of drowning. Those who do not drown suffer 15d6 points of damage per successful attack. Magical items that grant a target a means to breathe underwater function normally and prevent this effect, but Istishia can instantly desttoy any one such item by forfeiting one of his normal attacks. Items targeted for destruction do not gain a saving throw. Istishia cannot destroy artifacts in this manner.\n\nIstishia may leave a field of battle or the Prime Material Plane at any time by spending two rounds merging with a large body of water",
    briefSummary: "WOR. ALIGNMENT: Any",
    fullText: "WOR. ALIGNMENT: Any\n\nFaerun has many powers whose portfolios deal with water. Umberlee governs the oceans and ocean storms, Valkur strives to protect those who travel the waves, and Eldath has dominion over pools, springs, and waterfalls. Istishia (Is-TISH-ee-ah) is more abstract than all these deities. He represents water, but not any specific formation or body of water. He is a mutable yet dynamic deity who is dispassionate and difficult to pin down. He provides the atmosphere in which life is born, but not life itself. He furnishes a crucial resource, but apparently cares not how it is used. He is depicted as anything from an immense water elemental to a drop of rain to a water weird to a wave on the ocean. Istishia represents eternal transmutation that holds a fixed, essential nature at its core. He holds in his nature change accomplished over time, as water wears away stone, or sudden leaps from one state to another, as water changes to steam when heated. He is the guardian of all hidden treasures under water.\n\nLike all the elemental lords, Istishia is relatively unfeeling toward his followers on Abeir-Toril. His reactions are utterly unpredictable and thus, in an odd way, predictable in their unpredictability. The reasoning behind Istishia's actions is incomprehensible to most of Faerun's inhabitants, including his worshipers. The alien and uncaring stance of Istishia and the other elemental lords has led to the mistaken impression in the Realms that they are only lesser powers and their followers merely oddball cultists. During the Time of Troubles, Istishia was not spotted in the Realms.\n\nIstishia always sends a representative to accept offerings (given to his de-' vout worshipers) of water-hued fine fabrics that ripple like waves, gemstones in shades from clear to deepest emerald or sapphire, fine inks or dyes, or books or papers on which are written unsolved or unsolvable riddles or mathematical problems. These representatives can be anything from his priests to fish to water elementals. His gifts to his followers are most often the ability to travel easily through water, the knowledge to find something hidden in water, or a change in themselves (often a polymorph spell that changes a being's corporeal form, but sometimes a sudden insight into a problem) that allows them to accomplish a previously unattainable goal. The worshipers he favors and those he ignores seem chosen on a whim.",
    categories: ["Faerunian Gods"]
)

let embeddedDeity018: Deity = Deity(
    id: "iyachtu_xvim",
    name: "Iyachtu Xvim",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Lesser Power",
    plane: "Gehenna",
    alignment: "LE",
    status: nil,
    portfolio: "Tyranny, hatred",
    aliases: nil,
    domainName: "Chamada/Bastion of Hate",
    superior: "None (formerly Bane—now dead)",
    allies: "None (formerly Bane—now dead)",
    foes: "The entire Faerunian pantheon, but especially Cyric",
    symbol: "A pair of bright, glowing green eyes superimposed on the palm of an upright, human-shaped hand of utter blackness (Xvim Empowered) or (older) a pair of green, glowing eyes peering out of darkness",
    worshiperAlignments: "LN, N, CN, LE, NE, CE",
    avatarClassLevels: nil,
    avatarDescription: nil,
    briefSummary: "TURN UNDEAD: C: Yes, if neutral, SP: Yes, Cm: No",
    fullText: "TURN UNDEAD: C: Yes, if neutral, SP: Yes, Cm: No\n\nCMND. UNDEAD: C: Yes, if evil, SP: Yes, Cru: No\n\nAll clerics, specialty priests, and crusaders of Iyachtu Xvim receive religion (Faeriinian) as a bonus nonweapon proficiency.\n\nIyachtu Xvim attracts the same sort of cruel, power-hungry folk who worshiped Bane. Some are fascinated by the awe and fear they feel in his presence, some take comfort in the rigid rules and the promise that humankind will prevail over all through might, taming all Faerun, and others feel truly alive when engaged in the ruthless intrigue that is unending in the Church of Darkness. Followers of Xvim, priests and lay folk, are called Xvimists, while priests of the Godson are known as Xvimlar, and the elite specialty priests of the faith are known as authlims.\n\nXvimlar exult in destruction and in oppressing others and enjoy casually dealing pain. Kicking folk they pass, slamming doors on people, and hurling stones down busy streets at random are not uncommon acts for Xvimlar. Some Xvimlar are former Banites, since Banite clergy members were actively courted and converted by the Xvimlar under orders from their Cruel Xvimlar see Xvim as Bane's heir.\n\nXvimlar jokingly title their novices \"Vermin\" and apply the title \"Oppressor\" to those of 3rd level or less, \"Hatemaster\" to clergy of 4th through 8th level, \"Ruinlord\" to those of 9th through 15th level, and \"Tyrannar\" to clergy of 16th or greater level. Titles in the church are the same regardless of gender, and temples are run in a strictly hierarchical manner, with the faith being led by a High Tyrannar. Crusaders of the faith, of which there are few as of yet, report directly to a temple's high priest (usually a Ruinlord or Tyrannar), with one exclusive unit of crusaders and battle-hardened warriors directly at the High Tyrannar's disposal.\n\nThus far, Xvim has shown a preference for underground temples, especially ones converted from abandoned temples of Bane. However, some grand temples have been dedicated or rededicated to him in Thay, most notably in Bezantur, City of a Thousand Temples, where the Church of Darkness maintains the House of Iyachtu Xvim, a new stone building with a large central hall, two long wings, and ample living and storage facilities.\n\nDogma: Xvim delights in death and destruction, and encourages his devoted to emulate him. In Xvim's dark, twisted mind, nothing worthy is accomplished without the destruction of something else. Those who would follow Xvim must be as committed to destruction, oppression, and cruelty as he is. Xvim favors a crushing pecking order that rewards those who shove others aside for personal gain. Those at the top of the food chain prey on those at the bottom. Those at the bottom either survive (and become stronger) or perish—in which case, they were weak and did not belong in Xvim's camp anyway.\n\nNovice Xvimlar are charged as follows by senior clergy members: \"Obey or die in pain and utter destruction. Enslave or slay the weak, and be sure that they know their suffering is in Xvim's name and by his will. Cause pain and fearful obedience in others whenever prudent. Be a cruel, heartless tyrant, and Xvim shall be pleased. Slay the priests of other gods whenever you can do so without being identified by others. Capture tyrants and take them to senior clergy members to be delivered unto Xvim. Capture all wizards and bring their magic to the church—or bring them to Xvim's most senior servants so that they can be transformed into creatures who will do service to Xvim as guardians. Spread fear of Xvim over all the lands. Destroy whatever and whoever bars his will and see that word of his power spreads but that no one survives to describe your deeds in detail except mortals who worship him. Destroy all witnesses to secret acts, but leave alive survivors to tell of Xvim's power when spreading casual destruction. There is a delight in destruction—feel it, and indulge in it.\"\n\nDay-to-Day Activities: The Xvimlar are busily roaming Faerun, inspired by the coming out of their Cruel Master into open godhood. Wherever they go they are challenging and slaying clergy of Cyric (their acknowledged enemy) and urging still-faithful Banite priests to join in worship of Xvim—or perish at their hands. For the most part, they have been successful at converting the remaining ultra-orthodox Banite, who see Xvim as holding the most valid claim to succeed Bane.\n\nThe leaders and spies in this \"conversion\" work are the authlims— whose primary mission, though, is to kidnap especially ruthless and powerful people (tyrants) to take their spirits to Xvim for him to feed upon. „ Both sorts of priests of Xvim have as their secondary missions the slaugh- ta> ter of the priests and clergy members of all other faiths than Xvim's, the spreading of fear, and the enhancement of Xvim's reputation by acts of cruelty and tyranny. Eliminating other priests must be done covertly, however, lest all faiths rise up together against the church of Xvim and overwhelm it.\n\nHoly Days/Important Ceremonies: There are as yet no known calendar- related festivals in the church of Xvim, though some temples celebrate his Coming, albeit on different days. (Some decree is expected to fix a firm date for this in the near future.) Xvim expects his priests to pray to him whenever they take a life in his name (even if the heat of battle or flight continues) and to bow down to him in prayer morning and evening, preferably in front of a high altar.\n\nHigh rituals involve horrific sacrifices of intelligent creatures and depraved gladiatorial combats (observed by the assembled priests) between goaded and starved beasts and desperate unarmed captives, conducted amid fragile glass items that can be shattered to yield weapons that harm both the wielder and targets. The church is also rumored to conduct chanting dances wherein priests work themselves into frenzies and then attack slaves and lesser priests wildly but barehanded, kicking and fighting until at least one combatant falls bleeding (whereupon bells are struck to end the strife and the ritual). In this young faith, rituals are still developing and changing quickly.\n\nMajor Centers of Worship: The supreme head of the church of Xvim is High Tyrannar Fzoul Chembryl, who, assisted by Ruinlord Xana the Once-Martyred, rules in the name of the Godson from the Heart of the Hand, a subterranean temple beneath the remnants of Zhentil Keep. Several temples in Thay are growing rapidly in power, but Fzoul's abject loyalty, brilliant schemes, authlim spies, and beholder allies have kept him at the pinnacle of the faith of the New Darkness, and continue to do so. Xvim ensures Fzoul's loyalty by possessing him at regular intervals to thoroughly explore his thoughts and memories—and highly values his cunning experience with religious infighting and conducting intrigues.\n\nAffiliated Orders: The Church of Darkness has only one affiliated knightly order, the Brothers of the Black Fist, a still-forming order to which the crusaders of the faith belong and which commands fighters attracted to the discipline and decisive leadership of Xvim's forces. With Fzoul Chembryl as its High Tyrannar, the Church of Darkness is also likely to develop intimate ties to the Zhentarim if it is not so allied already.\n\nPriestly Vestments: Ritual vestments for an authlim are a blackened metal skullcap and a black amice (overmantle) with thin, bright green piping or braidwork worn over a long, black cassock with green maniples attached to its sleeves, so they flash green out of the black garb when the priest gestures. The garb is completed by a green ecclesiastical stole embroidered with the symbol of Xvim. Ritual garments for rank and file Xvimlar are a green surplice adorned on the breast with the symbol of Xvim worn over a plain black cassock. This outfit is augmented out of doors or in ritual processions with a black cope (overcloak) embroidered on the back with the symbol of Xvim, black gloves, and a black miter set with two green gems to represent the eyes of Xvim.\n\nAdventuring Garb: The adventuring priest of Xvim dresses like any armored priest, favoring black armor with green accessories. Everyday wear is black (often black robes) with green piping as trim, or with gloves, belts or sashes, collars, and pouches of a startlingly bright emerald hue. Authlims wear spiked and imposing black battle armor and sport black great helms fashioned into the likenesses of monsters' heads with green gems for the eyes.\n\n## Specialty Priests (Authlims)\n\nREQUIREMENTS: Strength 12, Wisdom 10\n\nPRIME REQ.: Strength, Wisdom\n\nALIGNMENT: LE\n\nWEAPONS: All nonmissile bludgeoning (wholly Type B) weapons and javelins\n\nARMOR: Any\n\nMAJOR SPHERESS: All, combat, divination, elemental, guardian, necromantic, summoning, thought, war\n\nMINOR SPHERES: Creation, healing (reversed forms only), law, sun (reversed forms only)\n\nMAGICAL ITEMS: Same as clerics\n\nREQ. PROFS: Modern languages (pick one from: beholder, bugbear, gargoyle, common giant, gnoll, goblin, High Shou, kobold, kuO'toan, Midani, minotaur, Mulhorandi, ogre, ore, sahuagin, Undercommon, Untheric, urd, yuan-ti)\n\nBONUS PROFS: Blind-fighting, modern languages (pick another from the previous listing)\n* Authlims gain a +1 to saving throws against spells cast by priests of Cyric or Bane. In addition, they gain a +1 to attack and damage rolls against these priests.\n* Authlims are unaffected by fear spells, though they may be affected by other emotion-affecting spells and by spell-like abilities that engender fear.\n* In the hands of an authlim, a rod of rulership works on 2d4+2x100 Hit Dice of creatures within 240 yards per charge, and a charge lasts for three turns. Saving throws vs. the ''rod of rulership's effects (when applicable) are at a —2 penalty.\n* Authlims are able to heal themselves once a day at will by calling on the divine power of Xvim. They can restore 2 hit points per experience level using this ability. They may only heal themselves in this manner, however.\n* At 3rd level, authlims are able to cast mace of Xvim (as the 2nd-level priest spell) once a day.\n* At 5th level, authlims are able to cast neutralize poison or poison (as the 4th-level priest spells) once a day.\n* At 5th level, authlims can generate an aura of fear in a 10-foot radius. This aura is similar to the fear 4th-level mage spell. Those who succeed in their saving throw against this effect still get an uneasy feeling, but this feeling does not affect their actions. The aura can be called up once per day, and lasts 1 round per level of the authlim. Fellow Xvimlar and other authlims, as well as diehard priests of Bane, are immune to its effects.\n* At 7th level, authlims are able to cast reaving blades and cure serious wounds (as the 4th-level priest spells) once a day.\n* At 9th level, authlims are able to cast a protection from good, 10' radius'' (as the reverse of the 4th-level priest spell protection from evil, 10' radius) once per day, lasting 1 round per level of the authlim.\n* At 10th level, authlims are able to cast cure critical wounds (as the 5th-level priest spell) once a day.\n* At 15th level, authlims are able to cast heal (as the 7th-level priest spell) once a tenday.\n* At 17th level, authlims are able to cast gate (as the 7th-level priest spell) once a month.\n* At 20th level, authlims are able to cast binding (as the 8th-level wizard spell) twice a month. They usually use this ability as a threat to bully a being they have gated into doing them a favor.\n\n## Xvimlar Spells\n\nIyachtu Xvim learned how to grant a great many of the spells his father was capable of granting to his followers while in his father's service. Dungeon Masters may wish to allow any or all of the spells exclusive to the church of Bane to be used also by the church of Iyachtu Xvim. The battletide spell detailed below is a spell brought to the knowledge of the church by Fzoul Chembryl when he joined Xvim's faith.\n\n| Name | Level | Sphere(s) |\n| --- | --- | --- |\n| Mace of Xvim | Level 2 | Combat |\n| Reaving Blades | Level 4 | Combat |\n| Battletide | Level 5 | Combat |\n\nCategory:Faerunian Gods",
    categories: ["Faerunian Gods"]
)

let embeddedDeity019: Deity = Deity(
    id: "kelemvor",
    name: "Kelemvor",
    book: "Faiths & Avatars",
    bookCode: "FA",
    rank: "Greater Power",
    plane: "the Gray Waste",
    alignment: "LN",
    status: nil,
    portfolio: "Death, the dead",
    aliases: "None",
    domainName: "Oinos/Crystal Spire",
    superior: "None",
    allies: "Mystra, Jergal",
    foes: "Cyric, Talona, Velsharoon",
    symbol: "An upright, bone-colored skeletal arm holding the golden scales of justice balanced evenly in its fist against a steel-gray field",
    worshiperAlignments: "Any",
    avatarClassLevels: "Fighter 33, Cleric 25, Mage 18",
    avatarDescription: "Kelemvor walks Faerun quietly and unassumingly when he comes to it. Since Kelemvor was until recently a mortal human warrior, he appears much as he did in life, as a square-jawed fighter with piercing green eyes in a dark, tanned face. He has a wild mane of black hair with a few streaks of gray in it and is clad in chain mail and dark leather. He always wears a wide belt bearing a large, cabochon-cut cat's-eye jewel at its front, but it appears to have no magical powers. He can draw from any sphere or school for his spells, but casts necromantic sphere spells and necromancy school spells at triple effect in all respects and with a -3 penalty to any applicable saving throws by the victims of such spells. Kelemvor will not create any sentient undead creatures, though he has no compunctions about using such to his own ends before dispatching them to a final judgment.\n\nAC -6; MV 15; HP 223; THAC0 -10; #AT 5/2\n\nDmg 2d4+17 (bastard sword +3, +12 STR, +2 spec, bonus in bastard sword)\n\nMR 80%; SZL (10 feet)\n\nSTR 24, DEX 17, CON 22, INT 13, Wis 13, CHA 18\n\nSpells P: 10/9/9/9/9/8/4, W : 5/5/5/5/5/3/3/2/1\n\nSaves PPDM 2, RSW 5, PP 4, BW 4, Sp 6\n\nSpecial Att/Def: Kelemvor wraps himself in a cloak of shadows when he wishes to hide from mortal eyes and observe. This cloak bestows upon him a 90% probability of being invisible while he moves or stands within a shadowy or dark place; it also works similar to a cloak of displacement in that any melee or missile attack aimed at Kelemvor automatically misses the first time. He is armed with both a bastard sword +3 and a rod of bone that projects death to mortals with one end and emits death sleep from the other end. He uses his bastard sword +3 only when brute force would prove the only remaining answer to a situation.\n\nKelemvor can make one attack with the rod of bone per round. The death end of the rod of bone causes any living creature to die instantly unless it makes a successful saving throw vs. death magic. This death affect can attack one being per round within Kelemvor's sight and causes dead victims to levitate a few inches upward and float in unbreakable stasis for 2 turns when they die. The death sleep end has a range of 150 yards and effects up to 8dlO creatures within a 120-foot cubic area. Kelemvor may select beings within the area of effect to not effect. Death sleep does not bring true death to anyone, but merely a comalike collapse and suspension of all bodily functions lasting for an entire day. Beings in death sleep do not breathe, but suffer no harm from lack of air to internal organs and the like; their bodies simply cease to function. Such beings cannot be awakened, even with rough handling. Removal of death sleep before a complete day passes requires the application of both dispel magic and remove curse. The nature of this magic is such that a being casting one of the needed spells is made aware of the necessity of the other.\n\nKelemvor is immune to all necromancy and necromantic spells, spell-l",
    briefSummary: "Kelemvor (KELL-ehm-vor), a former associate of Midnight, Cyric, and Adon during the events of the Godswar, inherited the portfolio of the god of the dead when Cyric lost those responsibilities following the Cyrinishad debacle.",
    fullText: "Kelemvor (KELL-ehm-vor), a former associate of Midnight, Cyric, and Adon during the events of the Godswar, inherited the portfolio of the god of the dead when Cyric lost those responsibilities following the Cyrinishad debacle. The first official act of the newly created god of the dead was to turn Cyric's Bone Castle into a gleaming tower of crystal, a symbol that this particular god of the dead would hide nothing from his subjects. He intends to impart justice among the dead in an even-handed and fair manner.\n\nKelemvor is kind, just, forthright, and earnest, though stern at times. He is not terribly clever for a power and tends to try to solve what he perceives as his immediate problems with direct action. Though he means well, he does not always see the difficulties down the road caused by short-term solutions.\n\nKelemvor has an unexpected ally, at least in terms of traditional godly alliances. He and Mystra, formerly the human Midnight, remain close. They were in love during their mortal lives, but whether this romance has kindled during their godly tenure is a matter they have thus far kept private.\n\nCyric, who lost his death portfolio to Kelemvor, is Kelemvor's bitter enemy. Cyric views Kelemvor as someone who pointedly and maliciously set out to steal a part of Cyric's rightful power. One traditional foe of the Faerunian god of the dead, Lathander, has not declared against Kelemvor, but is waiting to see if his actions live up to his promises.",
    categories: ["Faerunian Gods"]
)
